import React, { Component } from 'react';
import MyContext from '../contexts/MyContext';
import Menu from './MenuComponent';
import Reception from './ReceptionComponent';
import Kitchen from './KitchenComponent.js';
import Login from './LoginComponent';
import { Route, Routes, Navigate } from 'react-router-dom';

import Report from './ReportComponent';
import Category from './CategoryComponent';
import Product from './ProductComponent';
import Order from './OrderComponent';
import Customer from './CustomerComponent';
import Voucher from './VoucherComponent';

class Main extends Component {
  static contextType = MyContext;

  render() {
    const token = this.context.token || localStorage.getItem('token');
    const role = this.context.role || localStorage.getItem('role');

    // Nếu chưa đăng nhập -> Hiển thị trang Login
    if (!token) {
      return <Login />;
    }

    return (
      <div style={{ backgroundColor: '#F9F6F0', minHeight: '100vh', margin: 0, padding: 0 }}>
        {/* Chỉ hiển thị thanh điều hướng Admin nếu đúng là role admin */}
        {role === 'admin' && <Menu />}

        <div style={{ padding: '20px' }}>
          <Routes>
            {/* Giao diện dành riêng cho Admin */}
            {role === 'admin' && (
              <>
                <Route path="/admin" element={<Navigate to="/admin/report" />} />
                <Route path="/admin/report" element={<Report />} />
                <Route path="/admin/category" element={<Category />} />
                <Route path="/admin/product" element={<Product />} />
                <Route path="/admin/order" element={<Order />} />
                <Route path="/admin/customer" element={<Customer />} />
                <Route path="/admin/voucher" element={<Voucher />} />
              </>
            )}

            {/* Giao diện dành riêng cho Lễ tân */}
            {role === 'receptionist' && (
              <Route path="*" element={<Reception />} />
            )}

            {/* Giao diện dành riêng cho Bếp */}
            {role === 'kitchen' && (
              <Route path="*" element={<Kitchen />} />
            )}

            {/* Mặc định chuyển hướng nếu sai đường dẫn */}
            <Route path="*" element={<Navigate to={role === 'receptionist' ? '/admin/reception' : '/admin/report'} />} />
          </Routes>
        </div>
      </div>
    );
  }
}

export default Main;
